from pathlib import Path

path = Path("FrameNative/Views/SportsLiveViewV33.swift")
sports = path.read_text(encoding="utf-8")

# V36.1: keep this independent of whitespace/indentation generated by V35.
# Fail loudly if the expected live-player options are missing rather than
# silently shipping a build with the old startup tuning.
replacements = [
    ('":network-caching": 1400', '":network-caching": 1100'),
    ('":live-caching": 1400', '":live-caching": 1100'),
]
for old, new in replacements:
    if old in sports:
        sports = sports.replace(old, new, 1)
    elif new not in sports:
        raise SystemExit(f"V36.1: expected VLC option not found: {old}")

path.write_text(sports, encoding="utf-8")
print("Applied V36.1 robust live cache tuning (1100ms).")
